declare uid uuid:=auth.uid(); fp text;op mission_staff_abort_private.operations;src jsonb;
 m public.master_v2_sessions;r public.mission_run_state;result jsonb;native jsonb;pol mission_staff_abort_private.policy;
 q jsonb; code text; cnt integer;
begin
 if uid is null then raise exception 'STAFF_ABORT_NOT_AUTHORIZED' using errcode='42501';end if;
 if p_session is null or p_request is null or p_expected_master_version is null or p_expected_master_version<1
 or p_expected_run_version is null or p_expected_run_version<1 then raise exception 'STAFF_ABORT_INPUT' using errcode='22023';end if;
 fp:=mission_internal.fingerprint(jsonb_build_object('session',p_session,'actor',uid,
  'master_version',p_expected_master_version,'run_version',p_expected_run_version));
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,923090));
 select * into op from mission_staff_abort_private.operations where request_key=p_request for update;
 if found then
  if op.actor_user_id<>uid or op.master_session_id<>p_session or op.fingerprint<>fp
   then raise exception 'STAFF_ABORT_REQUEST_CONFLICT' using errcode='40001';end if;
  if op.state in('committed','rejected') then return op.receipt;end if;
  raise exception 'STAFF_ABORT_PENDING' using errcode='55000';
 end if;
 -- Authorization before ledger insertion prevents arbitrary session enumeration/audit pollution.
 src:=mission_staff_abort_private.source_v1(p_session);
 insert into mission_staff_abort_private.operations(request_key,actor_user_id,master_session_id,fingerprint,state)
 values(p_request,uid,p_session,fp,'pending');
 begin
  -- Same cursor->Master ordering as claim/authorize/finalizer; native scope locks all Combat rows.
  perform 1 from mission_generic_owner.role_window_cursors where master_session_id=p_session for update;
  perform public.master_v2_lock_scope(p_session);
  select * into strict m from public.master_v2_sessions where id=p_session for update;
  select * into strict r from public.mission_run_state where master_session_id=p_session for update;
  perform 1 from mission_generic_owner.work_items where master_session_id=p_session order by id for update;
  perform 1 from mission_generic_owner.dispatch_admissions where master_session_id=p_session for update;
  select * into strict pol from mission_staff_abort_private.policy where singleton for share;
  src:=mission_staff_abort_private.source_v1(p_session);
  if not pol.enabled or (src->>'kind'='quest' and not pol.quest_qualified) then raise exception 'STAFF_ABORT_UNAVAILABLE' using errcode='P0001';end if;
  if m.control_version<>p_expected_master_version or r.control_version<>p_expected_run_version
   then raise exception 'STAFF_ABORT_STALE' using errcode='P0001';end if;
  if m.closed_at is not null or m.stato not in('preparazione','in_corso','sospesa')
   or r.run_phase not in('preparazione','in_corso','sospesa')
   then raise exception 'STAFF_ABORT_TERMINAL_OR_CLOSING' using errcode='P0001';end if;
  if not mission_staff_abort_private.quiescent_v1(p_session) then raise exception 'STAFF_ABORT_NOT_QUIESCENT' using errcode='P0001';end if;
  if not (src->>'kind'='flow' and src->>'source_schema'='c1264-protected-flow-cleanup/1' and p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid) and not (src->>'kind'='quest' and src->>'source_state'='prepared') and not exists(select 1 from mission_ai_service_owner.capabilities where master_session_id=p_session and state='active') then raise exception 'STAFF_ABORT_POSTCONDITION' using errcode='P0001';end if;
  if src->>'kind'='quest' then
   execute 'select to_jsonb(q) from mission_factory_owner.quest_run_sources q where session_id=$1 for update' into strict q using p_session;
   if (q->>'control_version')::bigint<>(src->>'source_control_version')::bigint or q->>'state' not in('prepared','opening_pending','started')
    then raise exception 'STAFF_ABORT_NOT_QUIESCENT' using errcode='P0001';end if;
   insert into mission_staff_abort_private.quest_permits(master_session_id,request_key,actor_user_id,source_control_version,transaction_id,backend_pid)
    values(p_session,p_request,uid,(q->>'control_version')::bigint,txid_current(),pg_backend_pid());
   execute 'update mission_factory_owner.quest_run_sources set state=''cancelled'',control_version=control_version+1,terminal_at=clock_timestamp() where session_id=$1' using p_session;
   if not exists(select 1 from mission_staff_abort_private.quest_permits where master_session_id=p_session and consumed)
    then raise exception 'STAFF_ABORT_QUEST_PERMIT' using errcode='P0001';end if;
  end if;
  update mission_generic_owner.dispatch_admissions set enabled=false where master_session_id=p_session;
  update mission_generic_owner.flow_staff_sessions set enabled=false where master_session_id=p_session;
  -- Same native termination sequence as scene_close, without reward/role finalization/outcome.
  update public.combat_v2_sessions set state='annullato',closed_at=clock_timestamp()
   where master_session_id=p_session and state not in('chiuso','annullato');
  perform combat_effects_private.lifecycle_session_end(s.id) from public.combat_v2_sessions s
   where s.master_session_id=p_session and s.closed_at is not null;
  update public.master_v2_participants set engagement_state='concluso',left_at=coalesce(left_at,clock_timestamp())
   where session_id=p_session and engagement_state<>'concluso';
  update public.master_v2_sessions set stato='annullata',closed_at=clock_timestamp(),close_reason='staff_simulation_abort',
   control_version=control_version+1 where id=p_session;
  native:=mission_internal.sync_lifecycle(p_session,p_request,p_expected_master_version+1,p_expected_run_version,'annullata');
  update mission_ai_service_owner.capabilities set state='terminal',terminal_request_key=p_request,
   terminal_mode='abort',terminal_at=clock_timestamp() where master_session_id=p_session and state='active';
  if src->>'kind'='generic' then
   update mission_generic_owner.board_starts set state='aborted' where master_session_id=p_session and state<>'aborted';
   update mission_ai_board_owner.roster_reservations set state='released',released_at=clock_timestamp()
    where activation_id=(src->>'activation_id')::uuid and state='active';
   update mission_ai_board_owner.weekly_quota set state='released',released_at=clock_timestamp()
    where activation_id=(src->>'activation_id')::uuid and state='reserved';
   update mission_ai_board_owner.activations set state='disarmed',control_version=control_version+1
    where id=(src->>'activation_id')::uuid and current_session_id=p_session and state<>'disarmed';
  end if;
  if exists(select 1 from public.combat_v2_sessions s where s.master_session_id=p_session and
    (s.closed_at is null or public.combat_v2_values_written(s.id)))
   or exists(select 1 from mission_generic_owner.dispatch_admissions where master_session_id=p_session and enabled)
   then raise exception 'STAFF_ABORT_POSTCONDITION' using errcode='P0001';end if;
  select * into strict r from public.mission_run_state where master_session_id=p_session;
  result:=jsonb_build_object('schema','staff-simulation-abort/1','request_key',p_request,'master_session_id',p_session,
   'status','annullata','expected_master_version',p_expected_master_version,'expected_run_version',p_expected_run_version,'master_control_version',p_expected_master_version+1,'run_control_version',r.control_version,
   'operation_id',p_request,'audit_event_id',r.last_event_id,'resources_protected',true);
  update mission_staff_abort_private.operations set state='committed',receipt=result,completed_at=clock_timestamp()
   where request_key=p_request;
  return result;
 exception when raise_exception then
  get stacked diagnostics code=message_text;
  if code not in('STAFF_ABORT_UNAVAILABLE','STAFF_ABORT_STALE','STAFF_ABORT_TERMINAL_OR_CLOSING','STAFF_ABORT_NOT_QUIESCENT','STAFF_ABORT_QUEST_PERMIT','STAFF_ABORT_POSTCONDITION') then raise;end if;
  -- Entire mutation subtransaction has rolled back before this authoritative rejection.
  result:=jsonb_build_object('schema','staff-simulation-abort/1','request_key',p_request,'master_session_id',p_session,
   'status','rejected','reason_code',code,'operation_id',p_request,'expected_master_version',p_expected_master_version,'expected_run_version',p_expected_run_version);
  update mission_staff_abort_private.operations set state='rejected',receipt=result,completed_at=clock_timestamp() where request_key=p_request;
  return result;
 end;
end

